async function restoreEeprom(){const n=document.getElementById("eepromFile");if(!n.files||n.files.length===0){Promethe.toast("Choose an EEPROM file first.","error");return}const t=n.files[0];if(t.size<256){Promethe.toast("EEPROM image must be at least 256 bytes.","error");return}const i=new FormData;i.append("file",t);try{Promethe.toast("Uploading EEPROM...");const n=await fetch("/api/restoreeeprom",{method:"POST",body:i});if(!n.ok)throw new Error("restore failed");Promethe.toast("EEPROM restored. Waiting for reboot...");await Promethe.waitForOnline(18e4);Promethe.toast("Console is back online.","success");window.location.href="index.html"}catch(r){Promethe.toast("EEPROM restore failed.","error")}}window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear()};